raw_text:
{
  "spans": [
    {
      "label": "QUOTE",
      "head": "མདོ་ན་ཤ་ཆང་སོགས་འདོད་ཡོན་ལྔ་དང་། ཁྱད་པར་བུད་མེད་དུག་ལྟར་སྤང་དགོས་",
      "tail": "ཞེས་གསུངས་པ་དང་།"
    },
    {
      "label": "QUOTE",
      "head": "སྔགས་ན་ཤ་ཆང་སོགས་འདོད་ཡོན་ལྔ་དང་། ཁྱད་པར་བུད་མེད་སྨན་ལྟར་བསྟེན་དགོས་",
      "tail": "ཞེས་གསུངས་པ་འདི་གཉིས།"
    },
    {
      "label": "QUOTE",
      "frame": "བྲམ་ཟེ་ས་ར་ཧས།",
      "head": "མདའ་མཁན་གྱི་བུ་མོ་ཕྱག་རྒྱར་བཞེས་ནས། །ཁ་སང་ཕན་ཆད་བྲམ་ཟེ་ཡིན། །དེ་རིང་ཚུན་ཆད་དགེ་སློང་ཡིན། །ཚངས་པར་སྤྱོད་པ་དགེ་སློང་སྟེ། །ཧེ་རུ་ཀ་དཔལ་དགེ་སློང་མཆོག །",
      "tail": "གསུངས་སྐད།"
    },
    {
      "label": "QUOTE",
      "frame": "ཨོ་རྒྱན་གྱི་བསྟོད་པ་ན།",
      "head": "ལེ་བརྒན་དམར་པོའི་ཆོས་གོས་གསོལ་བ་ནི། །ཚུལ་ཁྲིམས་རྣམ་དག་སྡོམ་དང་ལྡན་པའི་རྟགས། །",
      "tail": "གསུངས།"
    },
    {
      "label": "QUOTE",
      "frame": "གྲུབ་ཐོབ་གླིང་ཆེན་རས་པའི་བསྟོད་པ་ན།",
      "head": "ལྷ་དང་མི་མོ་དང་འགྲོགས་ཀྱང་། །འཛག་པའི་དྲི་མ་མི་མངའ་བའི། །ཚངས་པར་སྤྱོད་པ་ཐམས་ཅད་ཀྱི། །མཆོག་ཏུ་གྱུར་པ་ཁྱོད་ལ་འདུད། །",
      "tail": "གསུངས།"
    },
    {
      "label": "QUOTE",
      "frame": "འཁོར་ལོ་བཅུ་པའི་མདོ་ལས།",
      "head": "ཁྱིམ་ན་གནས་ཤིང་། ཁ་སྤུ་མ་བྲེགས། ཆོས་གོས་ཀྱང་མ་གྱོན། ཚུལ་ཁྲིམས་ཀྱང་མ་མནོས་ཀྱང་། འཕགས་པའི་ཆོས་ཉིད་དང་ལྡན་པ་དེ་ཉིད། དོན་དམ་པའི་དགེ་སློང་ཞེས་བྱའོ། །",
      "tail": "གསུངས།"
    },
    {
      "label": "QUOTE",
      "frame": "འབྲུག་པ་ཀུན་ལེགས་ཀྱིས།",
      "head": "གསང་སྔགས་ཀྱི་བསྐྱེད་རྫོགས་འདིས་ཉོན་མོངས་པ་ཕྲ་ཞིབ་གཅོད་དགོས་པས་ད་རིམ་གཉིས་བསྒོམ། སྔགས་ལ་སྤྱོད་ཟེར་ནས་ནག་ཆང་བག་མེད་དུ་མ་བསྟེན། གནས་བརྟན་ཆེན་པོ་བཅུ་དྲུག་དང་ཇོ་བོ་དི་པཱཾ་ཀ་ར་སོགས་སྔགས་ཀྱི་བདག་པོར་འདུག་སྟེ་དེ་འདྲ་རང་མཛད་སྒྲོས་མི་གདའ། ཕྱི་འདུལ་བ་དང་ནང་གསང་སྔགས་པ་ཟེར་ཏེ། འདུལ་བ་དོན་དང་མཐུན་ན་གསང་སྔགས་དེ་ཁའི་ནང་ན་བཞུགས། སྔགས་ཀྱི་སྤྱོད་པ་འదిདྲོད་མ་ཐོབ་པའི་གང་ཟག་གིས་སྤྱད་ན། བོང་བུ་གཟིག་ལྤགས་བཀབ་ནས་ལོ་ཏོག་ཟོས་མཐར་གཞན་གྱིས་བསད་པ་བཞིན་འོང་བས། རེ་ཞིག་ཡིད་སྨོན་དུ་གྱིས་ལ་དངོས་སུ་མ་སྤྱོད་",
      "tail": "གསུངས།"
    },
    {
      "label": "QUOTE",
      "head": "དེ་ལྟ་བུའི་གང་ཟག་ལ་འདུལ་བ་ནས་གཏན་ནས་གནང་བ་མེད་",
      "tail": "ཅེས་གསུངས་པ་ཡིན་ནོ། །"
    },
    {
      "label": "QUOTE",
      "head": "འཇམ་པའི་དབྱངས་ནི་ལྷག་པའི་ལྷ། །དབྱངས་ཅན་མ་ནི་ལས་རྒྱ་སྟེ། །ངེས་པར་ཁོ་ན་བྱང་ཆུབ་པོ་",
      "tail": "ཅེས་གསུངས་པས་ན་"
    },
    {
      "label": "QUOTE",
      "head": "ཕྱི་རུ་ཉན་ཐོས་སྤྱོད་པ་སྐྱོང་ཞིང་། །ནང་དུ་གསང་སྔགས་རྡོ་རྗེ་འཛིན། །",
      "tail": "གསུངས།"
    },
    {
      "label": "QUOTE",
      "head": "ཕྱི་ལྟར་ལག་ལེན་འདུལ་བའི་ལུགས་སུ་སྤྱོད། །རྒྱུ་འབྲས་སྤང་བླང་ཞིབ་པའི་དགོས་པ་ཡོད། །ནང་ལྟར་གསང་སྔགས་ཐུན་མོངས་ལུགས་སུ་སྤྱོད། །བསྐྱེད་རྫོགས་དོན་དང་འབྲེལ་བའི་དགོས་པ་ཡོད། །གསང་བ་གསང་ཆེན་ཨ་ཏིའི་ལུགས་སུ་སྤྱོད། །ཚེ་གཅིག་འོད་སྐུར་གྲོལ་བའི་དགོས་པ་ཡོད། །",
      "tail": "གསུངས།"
    }
  ]
}
